INSERT INTO feature VALUES('unit-source-window','workflow','A unit''s papers keep the citation window',NULL,'implemented','ordinary',NULL,'A unit''s `## Sources` row citing a paper dated before the citation window''s cutoff, by its library key''s year or its arXiv identifier''s, names the newer work superseding it, `superseded by `<key>``, or states `exemplar: <why no newer work states what the unit builds>`. `unit:check`, `issue:file`, the issues workflow, `claim:next` and `pr:open` refuse a row with neither, and an issue the coordinator signed is never judged for it.',NULL,'.config/bodies/unit.json',NULL,NULL);
